import { supabase } from '@/lib/supabase';
import { rows, maybeOne, one, none } from './_query';

/**
 * notifications
 *
 * GENERATED by scripts/gen-data-modules.mjs. Safe to edit — regeneration skips
 * any module listed as hand-written in that script, so promote this file there
 * before making substantial changes.
 *
 * RLS decides what a caller can see; these functions do not re-check roles.
 */

const COLUMNS = 'id, school_id, user_id, message, type, timestamp, read_status, related_entity_id, related_entity_type, group_key, group_count, email_sent, created_at';

/** Everything in a school. */
export function listForSchool(schoolId) {
  return rows(
    supabase.from('notifications').select(COLUMNS).eq('school_id', schoolId)
      .order('created_at', { ascending: false }),
    'notifications.listForSchool',
  );
}

export function get(id) {
  return maybeOne(supabase.from('notifications').select(COLUMNS).eq('id', id), 'notifications.get');
}

/**
 * Equality filters, for call sites that don't have a named query yet.
 *
 * `where({ school_id, status })` maps each key to `.eq()`; an array value
 * becomes `.in()` and null becomes `.is(null)`. Prefer adding a named
 * function above when the same filter shows up more than once.
 */
export function where(filters = {}, { order, ascending = false, limit } = {}) {
  let q = supabase.from('notifications').select(COLUMNS);
  for (const [key, value] of Object.entries(filters)) {
    if (value === undefined) continue;
    if (value === null) q = q.is(key, null);
    else if (Array.isArray(value)) q = q.in(key, value);
    else q = q.eq(key, value);
  }
  if (order) q = q.order(order, { ascending });
  if (limit) q = q.limit(limit);
  return rows(q, 'notifications.where');
}

export function create(record) {
  return one(supabase.from('notifications').insert(record).select(COLUMNS), 'notifications.create');
}

export function update(id, patch) {
  return one(
    supabase.from('notifications').update(patch).eq('id', id).select(COLUMNS),
    'notifications.update',
  );
}

export function remove(id) {
  return none(supabase.from('notifications').delete().eq('id', id), 'notifications.remove');
}

/**
 * Watch for notifications addressed to one user in one school.
 *
 * base44 had `entities.Notification.subscribe(cb)`, which fired for every
 * change in the app and left callers to filter client-side. Postgres changefeeds
 * filter server-side, so this only wakes for rows that actually concern the
 * user — and RLS still applies, so nobody can subscribe to someone else's.
 *
 * Returns an unsubscribe function.
 */
export function subscribe({ userId, schoolId }, onChange) {
  if (!userId || !schoolId) return () => {};

  const channel = supabase
    .channel(`notifications:${schoolId}:${userId}`)
    .on(
      'postgres_changes',
      {
        event: '*',
        schema: 'public',
        table: 'notifications',
        filter: `user_id=eq.${userId}`,
      },
      (payload) => onChange(payload),
    )
    .subscribe();

  return () => {
    supabase.removeChannel(channel);
  };
}
